let timeData = [], pumpHouseValues = [], torrentValues = [], mcc1Values = [],
  mcc2Values = [], mcc3Values = [], mcc4AValues = [], mcc4BValues = [],
  mcc5Values = [], mcc6Values = [], streetLightValues = [],
  adminBuildingValues = [], substationValues = [], solarDrierValues = [],
  meshBeltValues = [];

context.panel.data.series.forEach((s) => {
  if (s.refId === 'O') {
    timeData = s.fields.find(f => f.name === 'Time')?.values ?? [];
    pumpHouseValues = s.fields.find(f => f.name === 'O')?.values ?? [];
  } else if (s.refId === 'AA') {
    torrentValues = s.fields.find(f => f.name === 'AA')?.values ?? [];
  } else if (s.refId === 'P') {
    mcc1Values = s.fields.find(f => f.name === 'P')?.values ?? [];
  } else if (s.refId === 'Q') {
    mcc2Values = s.fields.find(f => f.name === 'Q')?.values ?? [];
  } else if (s.refId === 'R') {
    mcc3Values = s.fields.find(f => f.name === 'R')?.values ?? [];
  } else if (s.refId === 'S') {
    mcc4AValues = s.fields.find(f => f.name === 'S')?.values ?? [];
  } else if (s.refId === 'T') {
    mcc4BValues = s.fields.find(f => f.name === 'T')?.values ?? [];
  } else if (s.refId === 'U') {
    mcc5Values = s.fields.find(f => f.name === 'U')?.values ?? [];
  } else if (s.refId === 'V') {
    mcc6Values = s.fields.find(f => f.name === 'V')?.values ?? [];
  } else if (s.refId === 'W') {
    streetLightValues = s.fields.find(f => f.name === 'W')?.values ?? [];
  } else if (s.refId === 'X') {
    adminBuildingValues = s.fields.find(f => f.name === 'X')?.values ?? [];
  } else if (s.refId === 'Y') {
    substationValues = s.fields.find(f => f.name === 'Y')?.values ?? [];
  } else if (s.refId === 'Z') {
    solarDrierValues = s.fields.find(f => f.name === 'Z')?.values ?? [];
  } else if (s.refId === 'AB') {
    meshBeltValues = s.fields.find(f => f.name === 'AB')?.values ?? [];
  }
});

// Calculate total daily consumption
let totalDailyConsumption = [];
for (let i = 0; i < timeData.length; i++) {
  let total = 0;
  total += pumpHouseValues[i] || 0;
  total += mcc1Values[i] || 0;
  total += mcc2Values[i] || 0;
  total += mcc3Values[i] || 0;
  total += mcc4AValues[i] || 0;
  total += mcc4BValues[i] || 0;
  total += mcc5Values[i] || 0;
  total += mcc6Values[i] || 0;
  total += streetLightValues[i] || 0;
  total += adminBuildingValues[i] || 0;
  total += solarDrierValues[i] || 0;
  total += meshBeltValues[i] || 0;
  totalDailyConsumption.push(total);
}

// Calculate the average total daily consumption
const averageTotalDailyConsumption = totalDailyConsumption.reduce((sum, value) => sum + value, 0) / totalDailyConsumption.length;

// Format dates
const formattedDates = timeData.map(d => {
  const date = new Date(d); // Parse the ISO string directly
  // Extract date components in UTC
  const year = date.getUTCFullYear();
  const month = date.getUTCMonth() + 1; // Month is zero-indexed
  const day = date.getUTCDate();
  let hour = date.getUTCHours() + 4; // Adjust the hour by 4 to account for your timezone
  const minute = date.getUTCMinutes();

  // Determine AM/PM and adjust hour for 12-hour format
  const ampm = hour >= 12 ? 'PM' : 'AM';
  hour = hour % 12;
  hour = hour ? hour : 12; // If hour is 0, set it to 12

  // Return formatted date string as 'MM/DD/YYYY, HH:mm AM/PM'
  return `${month}/${day}/${year}`;
});

return {
  title: {
    text: `Average Daily Consumption: {value|${averageTotalDailyConsumption.toFixed(2)} kwh/day}`,
    left: 'center',
    bottom: 0,
    textStyle: {
      fontSize: 20, // Increased the font size of the title text
      rich: {
        value: {
          color: '#00ff00',
          fontSize: 24, // Increased the font size of the value
          fontWeight: 'bold'
        }
      }
    }
  },
  tooltip: {
    trigger: 'axis',
