      type: 'cross'
    }
  },
  legend: {
    data: ['Pump House', 'MCC1', 'MCC2', 'MCC3', 'MCC4A', 'MCC4B', 'MCC5', 'MCC6', 'Street Light', 'Admin Building', 'Solar Drier', 'Mesh Belt', 'Substation', 'Torrent']
  },
  grid: {
    left: '5%',
