    data: formattedDates,
    axisLabel: {
      formatter: function (val) {
        const date = new Date(val);
        const month = date.getMonth() + 1; // Month is zero-indexed
        const day = date.getDate();
        return `${month}/${day}`;
      }
    }
  },
  yAxis: {
    type: 'value',
    name: 'Daily Power Consumption',
    nameLocation: 'middle',
    nameGap: 90,
    nameTextStyle: {
